import time
import math


def retry_with_backoff(func, max_retries=3, initial_delay=0.1, backoff_factor=2,
                       *, retry_on=(Exception,), max_delay=None, sleep=None):
    if isinstance(max_retries, bool) or not isinstance(max_retries, int) or max_retries < 0:
        raise ValueError("max_retries must be a non-negative integer")
    if isinstance(initial_delay, bool) or not isinstance(initial_delay, (int, float)) \
            or not math.isfinite(initial_delay) or initial_delay < 0:
        raise ValueError("initial_delay must be a finite non-negative number")
    if isinstance(backoff_factor, bool) or not isinstance(backoff_factor, (int, float)) \
            or not math.isfinite(backoff_factor) or backoff_factor < 1:
        raise ValueError("backoff_factor must be a finite number >= 1")
    if max_delay is not None:
        if isinstance(max_delay, bool) or not isinstance(max_delay, (int, float)) \
                or not math.isfinite(max_delay) or max_delay < 0:
            raise ValueError("max_delay must be None or a finite non-negative number")
    if not isinstance(retry_on, tuple) or len(retry_on) == 0 \
            or not all(isinstance(t, type) and issubclass(t, Exception) for t in retry_on):
        raise ValueError("retry_on must be a nonempty tuple of Exception subclasses")

    if sleep is None:
        sleep = time.sleep

    attempt = 0
    while True:
        try:
            return func()
        except BaseException as exc:
            retryable = isinstance(exc, Exception) and any(
                isinstance(exc, t) for t in retry_on
            )
            if not retryable or attempt >= max_retries:
                raise
            delay = initial_delay * (backoff_factor ** attempt)
            if max_delay is not None:
                delay = min(delay, max_delay)
            sleep(delay)
            attempt += 1
